var s = securecookie.New(hashKey, blockKey) // hashKey >= 32 bytes; nil blockKey = signed only

func setSession(w http.ResponseWriter, cart map[string]string) error {
	encoded, err := s.Encode("session", cart)
	if err != nil {
		return err
	}
	http.SetCookie(w, &http.Cookie{Name: "session", Value: encoded, Path: "/",
		Secure: true, HttpOnly: true, MaxAge: 1800})
	return nil
}
